{
  "correction_rules": [
    "Adjust forecasts downward when model shows persistent overestimation in early periods (e.g., 1-3 days) following recent spikes.",
    "Increase forecast sensitivity to recent low prices when sentiment is neutral or negative (sentiment=0.00), to avoid underestimating rebound potential.",
    "Apply mean reversion bias: if forecast is > 20% above recent 7-day average, reduce by 5-10% unless sentiment indicates bullish momentum.",
    "Avoid overshoot after sharp price spikes: if true outcome exceeds forecast by >15%, reduce next period’s forecast by 10-15% to prevent overcorrection.",
    "For 30-day horizon, if true outcome deviates >10% from forecast in 3+ consecutive days, apply a smoothing filter to reduce volatility amplification.",
    "When sentiment history is uniformly zero, assume no directional bias; use historical mean as baseline for correction unless volatility spikes."
  ]
}
